"use client";

/**
 * Behavioral Intelligence Dashboard
 * ==================================
 * 
 * Phase 3: Advanced Behavioral Intelligence Layer
 * 
 * Displays:
 * - Financial Health Score (Gauge)
 * - Savings Discipline
 * - Impulse Indicator
 * - Stress Indicator
 * - Behavioral Insights Panel
 * - Risk Flags (India-specific)
 * - Monthly Trend Visualization
 * 
 * UI Rules:
 * - Red = Risk
 * - Green = Discipline
 * - Amber = Warning
 * - Minimal tables
 * - Insight-first layout
 */

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Skeleton } from "@/components/ui/skeleton";
import {
  AlertTriangle,
  TrendingUp,
  TrendingDown,
  Target,
  PiggyBank,
  Activity,
  Shield,
  Info,
  CheckCircle,
  XCircle,
  AlertCircle,
  Zap,
  Calendar,
  IndianRupee,
} from "lucide-react";

// ============================================================
// Types
// ============================================================

interface BehavioralIndex {
  score: number;
  [key: string]: any;
}

interface BehavioralIndices {
  loss_aversion: BehavioralIndex;
  impulsivity: BehavioralIndex;
  habit_stability: BehavioralIndex;
  financial_stress: BehavioralIndex;
  savings_discipline: BehavioralIndex;
}

interface IndiaRisks {
  upi_micro_spend_flag: boolean;
  gambling_flag: boolean;
  loan_app_pattern_flag: boolean;
  emi_ratio: number;
  gambling_transaction_count?: number;
  loan_credit_count?: number;
}

interface RiskSignals {
  india_specific: IndiaRisks;
  high_impulsivity: boolean;
  high_stress: boolean;
  low_savings: boolean;
}

interface TemporalPatterns {
  trend: number;
  seasonality: number;
  volatility: number;
  weekly_pattern: Record<string, number>;
}

interface BehaviorProfile {
  temporal_patterns: TemporalPatterns;
  behavioral_indices: BehavioralIndices;
  risk_signals: RiskSignals;
  confidence: number;
  financial_health_score: number;
  data_quality: {
    transactions_90_days: number;
    total_transactions: number;
  };
}

interface Insight {
  type: "warning" | "positive" | "info";
  title: string;
  message: string;
  metric: string;
  value: any;
}

interface Nudge {
  type: "habit" | "friction" | "goal" | "awareness";
  priority: number;
  title: string;
  message: string;
  trigger: string;
  actionable: boolean;
}

interface InsightsResponse {
  insights: Insight[];
  nudges: Nudge[];
  top_nudge: Nudge;
  summary: string;
  financial_health_score: number;
  confidence: number;
}

// ============================================================
// Utility Functions
// ============================================================

function getScoreColor(score: number): string {
  if (score >= 0.7) return "text-green-600";
  if (score >= 0.4) return "text-amber-600";
  return "text-red-600";
}

function getScoreBg(score: number): string {
  if (score >= 0.7) return "bg-green-100";
  if (score >= 0.4) return "bg-amber-100";
  return "bg-red-100";
}

function getHealthColor(score: number): string {
  if (score >= 70) return "text-green-600";
  if (score >= 40) return "text-amber-600";
  return "text-red-600";
}

function getHealthBg(score: number): string {
  if (score >= 70) return "bg-green-500";
  if (score >= 40) return "bg-amber-500";
  return "bg-red-500";
}

function getInsightIcon(type: string) {
  switch (type) {
    case "warning":
      return <AlertTriangle className="h-4 w-4 text-amber-500" />;
    case "positive":
      return <CheckCircle className="h-4 w-4 text-green-500" />;
    default:
      return <Info className="h-4 w-4 text-blue-500" />;
  }
}

function getInsightBg(type: string): string {
  switch (type) {
    case "warning":
      return "border-amber-200 bg-amber-50";
    case "positive":
      return "border-green-200 bg-green-50";
    default:
      return "border-blue-200 bg-blue-50";
  }
}

function getNudgeIcon(type: string) {
  switch (type) {
    case "friction":
      return <Zap className="h-4 w-4 text-purple-500" />;
    case "goal":
      return <Target className="h-4 w-4 text-blue-500" />;
    case "habit":
      return <Calendar className="h-4 w-4 text-green-500" />;
    default:
      return <Info className="h-4 w-4 text-gray-500" />;
  }
}

// ============================================================
// Components
// ============================================================

function HealthGauge({ score, confidence }: { score: number; confidence: number }) {
  const radius = 80;
  const circumference = 2 * Math.PI * radius;
  const progress = (score / 100) * circumference;
  const offset = circumference - progress;

  return (
    <div className="flex flex-col items-center">
      <div className="relative">
        <svg width="200" height="200" className="transform -rotate-90">
          {/* Background circle */}
          <circle
            cx="100"
            cy="100"
            r={radius}
            stroke="#e5e7eb"
            strokeWidth="12"
            fill="none"
          />
          {/* Progress circle */}
          <circle
            cx="100"
            cy="100"
            r={radius}
            stroke={score >= 70 ? "#22c55e" : score >= 40 ? "#f59e0b" : "#ef4444"}
            strokeWidth="12"
            fill="none"
            strokeDasharray={circumference}
            strokeDashoffset={offset}
            strokeLinecap="round"
            className="transition-all duration-1000"
          />
        </svg>
        <div className="absolute inset-0 flex flex-col items-center justify-center">
          <span className={`text-4xl font-bold ${getHealthColor(score)}`}>
            {score.toFixed(0)}
          </span>
          <span className="text-sm text-gray-500">Health Score</span>
        </div>
      </div>
      <div className="mt-4 text-center">
        <p className="text-sm text-gray-600">
          Confidence: <span className="font-medium">{(confidence * 100).toFixed(0)}%</span>
        </p>
      </div>
    </div>
  );
}

function IndexCard({
  title,
  score,
  icon,
  description,
  inverse = false,
}: {
  title: string;
  score: number;
  icon: React.ReactNode;
  description: string;
  inverse?: boolean;
}) {
  const displayScore = inverse ? 1 - score : score;
  const percentage = (displayScore * 100).toFixed(0);

  return (
    <Card>
      <CardHeader className="pb-2">
        <div className="flex items-center justify-between">
          <CardTitle className="text-sm font-medium">{title}</CardTitle>
          {icon}
        </div>
      </CardHeader>
      <CardContent>
        <div className="space-y-2">
          <div className="flex items-center justify-between">
            <span className={`text-2xl font-bold ${getScoreColor(displayScore)}`}>
              {percentage}%
            </span>
            <Badge variant="outline" className={getScoreBg(displayScore)}>
              {displayScore >= 0.7 ? "Good" : displayScore >= 0.4 ? "Fair" : "Needs Work"}
            </Badge>
          </div>
          <Progress value={parseFloat(percentage)} className="h-2" />
          <p className="text-xs text-gray-500">{description}</p>
        </div>
      </CardContent>
    </Card>
  );
}

function RiskFlags({ risks }: { risks: IndiaRisks }) {
  const flags = [];

  if (risks.upi_micro_spend_flag) {
    flags.push({
      icon: <AlertCircle className="h-4 w-4" />,
      title: "UPI Micro-Spend Clustering",
      description: "High frequency of small UPI transactions detected",
      severity: "warning",
    });
  }

  if (risks.gambling_flag) {
    flags.push({
      icon: <XCircle className="h-4 w-4" />,
      title: "Gaming/Gambling Activity",
      description: `${risks.gambling_transaction_count || 0} transactions on gaming platforms`,
      severity: "danger",
    });
  }

  if (risks.loan_app_pattern_flag) {
    flags.push({
      icon: <AlertTriangle className="h-4 w-4" />,
      title: "Loan App Pattern",
      description: "Multiple loan app credits detected",
      severity: "warning",
    });
  }

  if (risks.emi_ratio > 0.4) {
    flags.push({
      icon: <IndianRupee className="h-4 w-4" />,
      title: "High EMI Burden",
      description: `${(risks.emi_ratio * 100).toFixed(0)}% of income goes to EMI`,
      severity: "warning",
    });
  }

  if (flags.length === 0) {
    return (
      <Alert className="border-green-200 bg-green-50">
        <CheckCircle className="h-4 w-4 text-green-600" />
        <AlertTitle className="text-green-800">No Risk Flags</AlertTitle>
        <AlertDescription className="text-green-700">
          No India-specific risk patterns detected in your transactions.
        </AlertDescription>
      </Alert>
    );
  }

  return (
    <div className="space-y-2">
      {flags.map((flag, i) => (
        <Alert
          key={i}
          className={
            flag.severity === "danger"
              ? "border-red-200 bg-red-50"
              : "border-amber-200 bg-amber-50"
          }
        >
          <span
            className={
              flag.severity === "danger" ? "text-red-600" : "text-amber-600"
            }
          >
            {flag.icon}
          </span>
          <AlertTitle
            className={
              flag.severity === "danger" ? "text-red-800" : "text-amber-800"
            }
          >
            {flag.title}
          </AlertTitle>
          <AlertDescription
            className={
              flag.severity === "danger" ? "text-red-700" : "text-amber-700"
            }
          >
            {flag.description}
          </AlertDescription>
        </Alert>
      ))}
    </div>
  );
}

function InsightsPanel({ insights }: { insights: Insight[] }) {
  if (insights.length === 0) {
    return (
      <div className="text-center py-8 text-gray-500">
        No insights available. Add more transactions for analysis.
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {insights.slice(0, 8).map((insight, i) => (
        <div
          key={i}
          className={`p-3 rounded-lg border ${getInsightBg(insight.type)}`}
        >
          <div className="flex items-start gap-2">
            {getInsightIcon(insight.type)}
            <div className="flex-1">
              <h4 className="font-medium text-sm">{insight.title}</h4>
              <p className="text-xs text-gray-600 mt-1">{insight.message}</p>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}

function NudgesPanel({ nudges }: { nudges: Nudge[] }) {
  if (nudges.length === 0) {
    return (
      <div className="text-center py-8 text-gray-500">
        No suggestions at this time.
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {nudges.slice(0, 5).map((nudge, i) => (
        <div
          key={i}
          className={`p-3 rounded-lg border ${
            nudge.priority === 1
              ? "border-red-200 bg-red-50"
              : nudge.priority === 2
              ? "border-amber-200 bg-amber-50"
              : "border-gray-200 bg-gray-50"
          }`}
        >
          <div className="flex items-start gap-2">
            {getNudgeIcon(nudge.type)}
            <div className="flex-1">
              <div className="flex items-center gap-2">
                <h4 className="font-medium text-sm">{nudge.title}</h4>
                {nudge.priority === 1 && (
                  <Badge variant="destructive" className="text-xs">
                    High Priority
                  </Badge>
                )}
              </div>
              <p className="text-xs text-gray-600 mt-1">{nudge.message}</p>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}

function WeeklyPattern({ pattern }: { pattern: Record<string, number> }) {
  const days = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
  const values = days.map((d) => pattern[d] || 0);
  const max = Math.max(...values);

  return (
    <div className="space-y-2">
      {days.map((day, i) => {
        const value = values[i];
        const percentage = max > 0 ? (value / max) * 100 : 0;

        return (
          <div key={day} className="flex items-center gap-2">
            <span className="w-3 text-xs text-gray-500">{day.slice(0, 3)}</span>
            <div className="flex-1 h-4 bg-gray-100 rounded overflow-hidden">
              <div
                className="h-full bg-blue-500 transition-all"
                style={{ width: `${percentage}%` }}
              />
            </div>
            <span className="w-16 text-xs text-right text-gray-600">
              ₹{value.toFixed(0)}
            </span>
          </div>
        );
      })}
    </div>
  );
}

// ============================================================
// Main Page
// ============================================================

export default function BehaviorPage() {
  const [profile, setProfile] = useState<BehaviorProfile | null>(null);
  const [insights, setInsights] = useState<InsightsResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchData() {
      try {
        const [profileRes, insightsRes] = await Promise.all([
          fetch("http://localhost:8000/api/behavior/summary"),
          fetch("http://localhost:8000/api/behavior/insights"),
        ]);

        if (!profileRes.ok || !insightsRes.ok) {
          throw new Error("Failed to fetch behavior data");
        }

        const profileData = await profileRes.json();
        const insightsData = await insightsRes.json();

        setProfile(profileData);
        setInsights(insightsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An error occurred");
      } finally {
        setLoading(false);
      }
    }

    fetchData();
  }, []);

  if (loading) {
    return (
      <div className="container mx-auto py-6 space-y-6">
        <Skeleton className="h-12 w-64" />
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <Skeleton className="h-64" />
          <Skeleton className="h-64" />
          <Skeleton className="h-64" />
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="container mx-auto py-6">
        <Alert variant="destructive">
          <AlertTriangle className="h-4 w-4" />
          <AlertTitle>Error</AlertTitle>
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      </div>
    );
  }

  if (!profile) {
    return (
      <div className="container mx-auto py-6">
        <Alert>
          <Info className="h-4 w-4" />
          <AlertTitle>No Data</AlertTitle>
          <AlertDescription>
            Add transactions to see behavioral insights.
          </AlertDescription>
        </Alert>
      </div>
    );
  }

  const indices = profile.behavioral_indices;

  return (
    <div className="container mx-auto py-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold">Behavioral Intelligence</h1>
          <p className="text-gray-500">
            Evidence-based insights into your financial behavior
          </p>
        </div>
        <Badge variant="outline">
          {profile.data_quality.transactions_90_days} transactions (90 days)
        </Badge>
      </div>

      {/* Summary */}
      {insights && (
        <Alert className="border-blue-200 bg-blue-50">
          <Info className="h-4 w-4 text-blue-600" />
          <AlertTitle className="text-blue-800">Summary</AlertTitle>
          <AlertDescription className="text-blue-700">
            {insights.summary}
          </AlertDescription>
        </Alert>
      )}

      {/* Main Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Health Score */}
        <Card className="lg:col-span-1">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Activity className="h-5 w-5" />
              Financial Health
            </CardTitle>
            <CardDescription>
              Composite score based on behavioral indices
            </CardDescription>
          </CardHeader>
          <CardContent className="flex justify-center">
            <HealthGauge
              score={profile.financial_health_score}
              confidence={profile.confidence}
            />
          </CardContent>
        </Card>

        {/* Behavioral Indices */}
        <Card className="lg:col-span-2">
          <CardHeader>
            <CardTitle>Behavioral Indices</CardTitle>
            <CardDescription>
              Key behavioral metrics derived from your transaction patterns
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <IndexCard
                title="Savings Discipline"
                score={indices.savings_discipline.score}
                icon={<PiggyBank className="h-4 w-4 text-green-500" />}
                description="Consistency and rate of savings over time"
              />
              <IndexCard
                title="Habit Stability"
                score={indices.habit_stability.score}
                icon={<Calendar className="h-4 w-4 text-blue-500" />}
                description="Predictability of recurring expenses"
              />
              <IndexCard
                title="Impulse Control"
                score={indices.impulsivity.score}
                icon={<Zap className="h-4 w-4 text-amber-500" />}
                description="Control over discretionary spending"
                inverse
              />
              <IndexCard
                title="Financial Stress"
                score={indices.financial_stress.score}
                icon={<Shield className="h-4 w-4 text-red-500" />}
                description="Balance volatility and buffer adequacy"
                inverse
              />
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Insights and Nudges */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Insights */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <TrendingUp className="h-5 w-5" />
              Behavioral Insights
            </CardTitle>
            <CardDescription>
              Evidence-based observations from your spending patterns
            </CardDescription>
          </CardHeader>
          <CardContent>
            {insights && <InsightsPanel insights={insights.insights} />}
          </CardContent>
        </Card>

        {/* Nudges */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Target className="h-5 w-5" />
              Suggested Actions
            </CardTitle>
            <CardDescription>
              Prioritized recommendations based on your profile
            </CardDescription>
          </CardHeader>
          <CardContent>
            {insights && <NudgesPanel nudges={insights.nudges} />}
          </CardContent>
        </Card>
      </div>

      {/* Risk Flags and Weekly Pattern */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* India-Specific Risks */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <AlertTriangle className="h-5 w-5" />
              Risk Flags
            </CardTitle>
            <CardDescription>
              India-specific financial risk patterns
            </CardDescription>
          </CardHeader>
          <CardContent>
            <RiskFlags risks={profile.risk_signals.india_specific} />
          </CardContent>
        </Card>

        {/* Weekly Pattern */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Calendar className="h-5 w-5" />
              Weekly Spending Pattern
            </CardTitle>
            <CardDescription>
              Average spending by day of week
            </CardDescription>
          </CardHeader>
          <CardContent>
            <WeeklyPattern pattern={profile.temporal_patterns.weekly_pattern} />
          </CardContent>
        </Card>
      </div>

      {/* Detailed Metrics */}
      <Card>
        <CardHeader>
          <CardTitle>Detailed Metrics</CardTitle>
          <CardDescription>
            Raw values for each behavioral index
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
            <div>
              <span className="text-gray-500">Savings Rate</span>
              <p className="font-medium">
                {(indices.savings_discipline.savings_rate * 100).toFixed(1)}%
              </p>
            </div>
            <div>
              <span className="text-gray-500">Buffer Days</span>
              <p className="font-medium">
                {indices.financial_stress.buffer_days.toFixed(0)} days
              </p>
            </div>
            <div>
              <span className="text-gray-500">Micro-Txn Ratio</span>
              <p className="font-medium">
                {(indices.impulsivity.micro_txn_ratio * 100).toFixed(1)}%
              </p>
            </div>
            <div>
              <span className="text-gray-500">Category CV</span>
              <p className="font-medium">
                {(indices.habit_stability.category_cv * 100).toFixed(1)}%
              </p>
            </div>
            <div>
              <span className="text-gray-500">Post-Income Velocity</span>
              <p className="font-medium">
                {(indices.loss_aversion.post_income_velocity * 100).toFixed(1)}%
              </p>
            </div>
            <div>
              <span className="text-gray-500">Credit Dependency</span>
              <p className="font-medium">
                {(indices.financial_stress.credit_dependency * 100).toFixed(1)}%
              </p>
            </div>
            <div>
              <span className="text-gray-500">Spending Trend</span>
              <p className="font-medium">
                {profile.temporal_patterns.trend > 0 ? "+" : ""}
                {(profile.temporal_patterns.trend * 100).toFixed(1)}%
              </p>
            </div>
            <div>
              <span className="text-gray-500">Volatility</span>
              <p className="font-medium">
                {(profile.temporal_patterns.volatility * 100).toFixed(1)}%
              </p>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}